-- ============================================
-- LUMA — Thème 8 : LONG 2/3 x4 — Une alliance à nouer entre plusieurs royaumes
-- ============================================


update scenarios set content = '{"characters": {"king": "le roi", "princess": "la princesse", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "king", "text": "Emissary, welcome. As you know, our kingdom and Valemoor have been enemies for generations.", "text_fr": "Émissaire, bienvenue. Comme vous le savez, notre royaume et Valemoor sont ennemis depuis des générations.", "choices": [{"text": "Your Majesty, I believe peace between your kingdoms is possible, if both sides are willing.", "text_fr": "Votre Majesté, je crois que la paix entre vos royaumes est possible, si les deux camps sont prêts.", "next": "n2"}, {"text": "What would it take for you to consider an alliance with Valemoor?", "text_fr": "Que faudrait-il pour que vous envisagiez une alliance avec Valemoor ?", "next": "n2b"}]}, "n2": {"speaker": "king", "text": "Willing? Their king murdered my grandfather in cold blood, emissary. Willing seems unlikely.", "text_fr": "Prêt ? Leur roi a assassiné mon grand-père de sang-froid, émissaire. ''Prêt'' semble improbable.", "choices": [{"text": "That wound runs deep, I understand. But the current king was but a child then.", "text_fr": "Cette blessure est profonde, je comprends. Mais le roi actuel n''était qu''un enfant à l''époque.", "next": "n3"}, {"text": "Perhaps it''s time the cycle of vengeance ends, for both your peoples'' sake.", "text_fr": "Peut-être est-il temps que le cycle de vengeance se termine, pour le bien de vos deux peuples.", "next": "n3"}]}, "n2b": {"speaker": "king", "text": "Full reparations, an apology before my court, and guaranteed trade rights for a decade.", "text_fr": "Des réparations complètes, des excuses devant ma cour, et des droits commerciaux garantis pendant une décennie.", "choices": [{"text": "Those are steep demands, but perhaps a starting point for negotiation.", "text_fr": "Ce sont des demandes exigeantes, mais peut-être un point de départ pour la négociation.", "next": "n3"}]}, "n3": {"speaker": "king", "text": "(Studies you carefully) You speak boldly for an emissary. Why should I trust your judgment?", "text_fr": "(Vous étudie attentivement) Vous parlez avec audace pour un émissaire. Pourquoi devrais-je faire confiance à votre jugement ?", "choices": [{"text": "Because I have no allegiance to either crown — only to peace itself.", "text_fr": "Parce que je n''ai aucune allégeance envers aucune couronne — seulement envers la paix elle-même.", "next": "n4"}, {"text": "You needn''t trust my judgment. Trust your own, once you hear what Valemoor offers.", "text_fr": "Vous n''avez pas à faire confiance à mon jugement. Faites confiance au vôtre, une fois que vous entendrez ce que Valemoor propose.", "next": "n4"}]}, "n4": {"speaker": "king", "text": "Very well. What does Valemoor''s king propose, precisely?", "text_fr": "Très bien. Que propose précisément le roi de Valemoor ?", "choices": [{"text": "A formal apology, shared trade routes, and a royal marriage to seal the peace.", "text_fr": "Des excuses officielles, des routes commerciales partagées, et un mariage royal pour sceller la paix.", "next": "n5"}]}, "n5": {"speaker": "king", "text": "A marriage? That''s... unexpected. My daughter would need to agree to such terms.", "text_fr": "Un mariage ? C''est... inattendu. Ma fille devrait accepter de telles conditions.", "choices": [{"text": "Of course — no alliance should be built on anyone''s unwilling sacrifice.", "text_fr": "Bien sûr — aucune alliance ne devrait être construite sur un sacrifice non consenti.", "next": "n6"}, {"text": "Perhaps she should be part of these discussions directly.", "text_fr": "Peut-être devrait-elle faire partie de ces discussions directement.", "next": "n6b"}]}, "n6": {"speaker": "king", "text": "A wise sentiment. I shall summon her to hear her thoughts on this matter.", "text_fr": "Un sentiment sage. Je vais la convoquer pour entendre ses pensées sur cette question.", "choices": [{"text": "That seems the fairest path forward, Your Majesty.", "text_fr": "Cela semble être la voie la plus juste, Votre Majesté.", "next": "n7"}]}, "n6b": {"speaker": "king", "text": "An unusual suggestion for an emissary to make, but... not without merit.", "text_fr": "Une suggestion inhabituelle pour un émissaire, mais... pas sans mérite.", "choices": [{"text": "Diplomacy should include those most affected by its outcomes.", "text_fr": "La diplomatie devrait inclure ceux les plus affectés par ses résultats.", "next": "n7"}]}, "n7": {"speaker": "princess", "text": "(Enters) Father summoned me? I''ve heard whispers of this... alliance proposal.", "text_fr": "(Entre) Père m''a convoquée ? J''ai entendu des murmures de cette... proposition d''alliance.", "choices": [{"text": "Princess, your voice matters greatly in this decision. What are your thoughts?", "text_fr": "Princesse, votre voix compte énormément dans cette décision. Quelles sont vos pensées ?", "next": "n8"}]}, "n8": {"speaker": "princess", "text": "Honestly? I''ve long believed this feud serves no one but old grudges. I''m... willing to consider it.", "text_fr": "Honnêtement ? Je crois depuis longtemps que cette querelle ne sert que de vieilles rancunes. Je suis... prête à considérer ça.", "choices": [{"text": "That''s a brave and generous perspective, princess.", "text_fr": "C''est une perspective courageuse et généreuse, princesse.", "next": "n9"}, {"text": "Would you like to meet Valemoor''s prince before deciding fully?", "text_fr": "Aimeriez-vous rencontrer le prince de Valemoor avant de décider pleinement ?", "next": "n9b"}]}, "n9": {"speaker": "king", "text": "(Looks between you both) If my daughter is willing to consider this path... I will not stand in the way.", "text_fr": "(Regarde entre vous deux) Si ma fille est prête à considérer cette voie... je ne me mettrai pas en travers.", "choices": [{"text": "This is a remarkable step toward lasting peace, Your Majesty.", "text_fr": "C''est un pas remarquable vers une paix durable, Votre Majesté.", "next": "n10"}]}, "n9b": {"speaker": "princess", "text": "That... would actually put my mind at ease, yes. I''d like that.", "text_fr": "Ça... me rassurerait vraiment, oui. J''aimerais ça.", "choices": [{"text": "I''ll arrange that meeting promptly, princess.", "text_fr": "Je vais organiser cette rencontre rapidement, princesse.", "next": "n10"}]}, "n10": {"speaker": "king", "text": "Send word to Valemoor. Let us begin these talks in earnest, emissary.", "text_fr": "Envoyez un message à Valemoor. Commençons ces discussions sérieusement, émissaire.", "choices": [{"text": "I will carry your words myself, Your Majesty. This is the beginning of something historic.", "text_fr": "Je porterai vos mots moi-même, Votre Majesté. C''est le début de quelque chose d''historique.", "next": "end_alliance"}]}, "end_alliance": {"speaker": "narrator", "text": "(Months later, the two kingdoms sign a historic peace treaty, ending generations of conflict.)", "text_fr": "(Des mois plus tard, les deux royaumes signent un traité de paix historique, mettant fin à des générations de conflit.)", "end": true, "ending_label": "Une alliance historique nouée par la diplomatie 👑🕊️"}}}'::jsonb, is_playable = true
where title = 'Une alliance à nouer entre plusieurs royaumes'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
